local zones = {
	[947] = {
		name = "Azeroth",
		short = "Vor zehntausend Jahren folgten die Hochgeborenen Kalimdors, berauscht von der Macht des Brunnens der Ewigkeit, dem Ruf des gefallenen Titanen Sargeras und rissen ein Tor für die Brennende Legion auf.",
		full = "Vor zehntausend Jahren folgten die Hochgeborenen Kalimdors, berauscht von der Macht des Brunnens der Ewigkeit, dem Ruf des gefallenen Titanen Sargeras und rissen ein Tor für die Brennende Legion auf. Malfurion Sturmgrimm und der Widerstand der Kaldorei zerschmetterten dieses Tor mit der Drachenseele und schleuderten Sargeras zurück in den Wirbelnden Nether, doch der Zusammenbruch des Brunnens zerbrach die Welt selbst. Das alte Kalimdor versank in Feuer und Flut; zerschlagene Kontinente erhoben sich aus den Trümmern, und das ertrunkene Herz des Landes wurde zum Großen Meer, in dem der Mahlstrom dort tobt, wo einst der Brunnen lag.",
		source = "https://warcraft.wiki.gg/wiki/Azeroth",
	},
	[1411] = {
		name = "Durotar",
		short = "Rissig und rot liegt Durotar da, ein Land aus Klippen und Schluchten, trocken und heiß, arm an Wasser und an allem, was grünt. Es liegt an der Ostküste von Kalimdor.",
		full = "Rissig und rot liegt Durotar da, ein Land aus Klippen und Schluchten, trocken und heiß, arm an Wasser und an allem, was grünt. Es liegt an der Ostküste von Kalimdor. Die Orcs finden darin eine herbe Schönheit, die an Draenor erinnert. Nach dem Dritten Krieg führte Kriegshäuptling Thrall sein Volk hierher, um eine neue Heimat zu errichten, und er benannte sie nach seinem ermordeten Vater Durotan.\n\nDer Frieden hielt nicht an. Großadmiral Daelin Proudmoore, ein Held des Zweiten Krieges und kein Freund der Orcs, brachte eine große Flotte aus Kul Tiras gegen Durotar, fest entschlossen, die Horde zu zerschlagen, bevor sie Wurzeln fassen konnte. Seine Tochter Jaina Proudmoore entschied sich anders. Bei Theramore wandte sie sich gegen ihren eigenen Vater und kämpfte an Thralls Seite, und Daelin fiel in der Schlacht, ehe die beiden sich versöhnen konnten. Aus Dankbarkeit ließ Thrall Jainas Soldaten unversehrt nach Theramore abziehen.\n\nDie Trolle der Darkspear halten als Verbannte die Südküste. Ihr eigener Hexendoktor Zalazane vertrieb sie von ihrer Heimat auf den Echoinseln, und sie konnten die Inseln bis heute nicht zurückerobern.",
		source = "https://warcraft.wiki.gg/wiki/Durotar_(Classic)",
	},
	[1412] = {
		name = "Mulgore",
		short = "Die Tauren wanderten Jahrhunderte lang ohne eigenes Land umher. Dann begegneten sie Thrall und seinen Orcs, als diese auf Kalimdor landeten, und Cairne Bloodhoof erkannte verwandte Seelen mit Ehre und Kraft.",
		full = "Die Tauren wanderten Jahrhunderte lang ohne eigenes Land umher. Dann begegneten sie Thrall und seinen Orcs, als diese auf Kalimdor landeten, und Cairne Bloodhoof erkannte verwandte Seelen mit Ehre und Kraft. Mit Thralls Geleit führte Cairne sein Volk nach Mulgore, und mit der Hilfe der Orcs trieb der Stamm der Bloodhoof die Zentauren zurück und nahm das Grasland in Besitz.\n\nEs ist ein geschütztes Tal, eine große Weide aus grünem Gras mit wenigen Bäumen, auf allen Seiten von Bergen umschlossen, mit einem einzigen Pass, der hinausführt. In der Mitte erheben sich die Klippen von Thunder Bluff über den Feldern und werfen lange Schatten über die Ebene. Auf dieser Mesa errichtete Cairne eine Zuflucht, in der Tauren aller Stämme willkommen sind, und die verstreuten Stämme haben sich unter seiner Herrschaft vereint.\n\nZelte und Fellhütten stehen neben Windmühlen, die die Getreidemühlen antreiben, und geschnitzte Totems säumen jede Straße. Die Zentauren überfallen die Ebenen noch immer, doch die Festungen auf der Mesa haben ihnen standgehalten. Jeder Tauren, der volljährig wird, muss in die Wildnis von Mulgore hinausgehen und sich in der Großen Jagd beweisen.",
		source = "https://warcraft.wiki.gg/wiki/Mulgore_(Classic)",
	},
	[1413] = {
		name = "Das Brachland",
		short = "Der Staub hier war nicht immer Staub. Dieses Land war einst Wald, gepflegt von den Nachtelfen, und mehrere ihrer großen Städte standen hier.",
		full = "Der Staub hier war nicht immer Staub. Dieses Land war einst Wald, gepflegt von den Nachtelfen, und mehrere ihrer großen Städte standen hier. Nach der Großen Zerschlagung verwandelten Krieg und Unglück das grüne Tal in eine sonnenverbrannte Ebene. Es ist heiß und größtenteils flach, mit verstreuten Hügeln und einigen Oasen, wo sich das Wasser sammelt.\n\nUnzählige Generationen lang zogen die Tauren über diese Ebenen und folgten den Kodos und den Donnerechsen. Zentauren jagten sie zum Vergnügen. Die Tauren wehrten sich, wenn sie mussten, doch sie liebten den Krieg nicht und brachen lieber ihre Zelte ab und zogen weiter. Auf ein Jahr Frieden folgte stets ein Jahr Krieg. Dann gingen Thralls Orcs und die Trolle der Darkspear an Land und marschierten Seite an Seite mit den Tauren der Bloodhoof gegen die Zentauren.\n\nNun hält die Horde das meiste davon. Orc-Höfe und Wachtürme sprenkeln das Gras, und die Goldstraße zieht sich von Norden nach Süden durch das Land. Stacheleber und Zentauren überfallen es von allen Seiten, und Kultisten der Burning Blade treiben im Norden ihr Werk.",
		source = "https://warcraft.wiki.gg/wiki/Barrens_(Classic)",
	},
	[1414] = {
		name = "Kalimdor",
		short = "Als die Hochgeborenen fort waren, entschieden die Nachtelfen, die auf dem zerbrochenen Kontinent blieben, sich abzuschotten. Ein Nebelschleier legte sich über das Land und verbarg es vor vorbeifahrenden Seeleuten.",
		full = "Als die Hochgeborenen fort waren, entschieden die Nachtelfen, die auf dem zerbrochenen Kontinent blieben, sich abzuschotten. Ein Nebelschleier legte sich über das Land und verbarg es vor vorbeifahrenden Seeleuten. Bei den Menschen lebte Kalimdor nur als alte Legende fort, von einem Land, das zerbrochen und unter den Wellen versunken war. Die Hochelfen von Quel'Thalas wussten es besser, denn Nachtelfen hatten sie über die langen Jahre besucht.\n\nSelbst als der Dritte Krieg begann, hielten die meisten Menschen Kalimdor noch für eine Geschichte. Der eigene Botschafter der Kirin Tor am Hof von König Terenas gehörte zu den Zweiflern. Einige hörten auf Medivhs Warnung und segelten nach Westen, unter ihnen Thralls neue Horde und die Expedition von Jaina Proudmoore. Sie fanden einen ganzen Kontinent, mit Eis und Wald im Norden und Wüste im Süden. Die Horde hält jetzt die zentralen und östlichen Länder, und die Nachtelfen halten sich im Nordwesten.",
		source = "https://warcraft.wiki.gg/wiki/Kalimdor",
	},
	[1415] = {
		name = "Östliche Königreiche",
		short = "Die Östlichen Königreiche waren nicht immer viele Länder.",
		full = "Die Östlichen Königreiche waren nicht immer viele Länder. Einst gehörten sie zu einem einzigen Kontinent, bevor die Große Teilung die Welt zerriss und die zerbrochenen Stücke zurückließ, die man heute Azeroth, Khaz Modan und Lordaeron nennt, wobei sich Quel'Thalas an den Norden jenes letzten zerschlagenen Landes klammert, bis heute ungewiss, ob es ein eigenes Land ist oder nur ein Winkel eines anderen.\n\nÜber diese Bruchstücke hinweg erheben sich die Berge von Khaz Modan und das Rotkammgebirge wie ein Rückgrat durch das Herz des Kontinents, und um sie herum überdauern die alten Völker: Zwerge und Gnome in ihren tiefen Hallen, Menschen in ihren Königreichen, Hochelfen in ihren Wäldern, und nun die Verlassenen, die sich dort erhoben haben, wo einst Lordaerons Volk lebte. Auch Orcs, Goblins, Naga und Oger haben ihren Weg in diese Lande gefunden, obwohl keiner von ihnen hier geboren wurde.\n\nDie Narben jenes ersten Bruchs sind noch immer die Wahrheit dieses Ortes. Jede Grenze hier, jede Meerenge und jeder Streifen versunkenen Landes zwischen einem Königreich und dem nächsten erinnert daran, dass die Östlichen Königreiche einst ein Ganzes waren und es nicht mehr sind.",
		source = "https://warcraft.wiki.gg/wiki/Eastern_Kingdoms",
	},
	[1416] = {
		name = "Alteracgebirge",
		short = "Regen fällt auf diese Gipfel öfter als nicht, und der Himmel bleibt grau unter schweren Wolken. Wald bedeckt die Hänge unterhalb des Schnees auf den höchsten Lagen.",
		full = "Regen fällt auf diese Gipfel öfter als nicht, und der Himmel bleibt grau unter schweren Wolken. Wald bedeckt die Hänge unterhalb des Schnees auf den höchsten Lagen. Am Fuß der Berge brachen Menschen und Hochelfen in der letzten Schlacht der Trollkriege das Imperium der Amani.\n\nZwei Mächte standen hier einst. Alterac war ein Stadtstaat zwischen den Gipfeln, der dazu kam, einen großen Teil der Nordlande zu beherrschen. Dalaran, die Stadt der Kirin Tor, stand am Lordameresee. Alterac fiel im Zweiten Krieg wegen seines Verrats. Dalaran wurde im Dritten Krieg zerstört, und seine überlebenden Zauberer haben sich hinter einer Kuppel aus Magie eingeschlossen.\n\nDie Crushridge-Oger halten die Ruinen von Alterac. Das Syndikat, eine Schar von Schurken, die Aliden Perenolde, ein Prinz des gefallenen Königshauses, um sich gesammelt hat, hält Strahnbrad und das Ackerland, und die beiden streiten um den Rest. Tief in den Bergen streiten die Frostwolf-Orcs und die Zwerge der Stormpikegarde um ein eigenes Tal.",
		source = "https://warcraft.wiki.gg/wiki/Alterac_Mountains_(Classic)",
	},
	[1417] = {
		name = "Arathihochland",
		short = "König Thoradin baute Strom, die Hauptstadt von Arathor, in diesem trockenen, zerklüfteten Land. In ihrer Nähe errichtete er eine große Mauer, um sein Volk vor den Amani-Trollen zu schützen.",
		full = "König Thoradin baute Strom, die Hauptstadt von Arathor, in diesem trockenen, zerklüfteten Land. In ihrer Nähe errichtete er eine große Mauer, um sein Volk vor den Amani-Trollen zu schützen. Das Imperium fiel, und die Kaiserliche Wache, die zurückblieb, gründete Stromgarde in der alten Stadt. Thoradinswall zieht sich noch immer am Nordrand entlang, eingestürzt und weit klaffend.\n\nStromgarde entging der Seuche der Geißel und fiel dann an das Syndikat und die Oger der Felsfäuste. Der Rest seiner Armee floh aus der Stadt in einen kleinen Canyon im Norden, der heute die Zuflucht heißt. Prinz Galen Trollbann führt die menschlichen Verteidiger, und sie, das Syndikat und die Oger kämpfen noch immer um die zerstörte Stadt.\n\nIm Osten hält die Horde Hammerfall, ein Lager für gefangene Orcs, das sie übernahm und zu Ehren des gefallenen Kriegshäuptlings Orgrim Schicksalshammer umbenannte.",
		source = "https://warcraft.wiki.gg/wiki/Arathi_Highlands_(Classic)",
	},
	[1418] = {
		name = "Ödland",
		short = "Das Ödland ist rissige, trockene Erde, übersät mit Felsbrocken und durchschnitten von gewundenen Schluchten, auf allen Seiten von Bergen eingeschlossen.",
		full = "Das Ödland ist rissige, trockene Erde, übersät mit Felsbrocken und durchschnitten von gewundenen Schluchten, auf allen Seiten von Bergen eingeschlossen. Nur die zähesten Geschöpfe überleben hier, darunter Kojoten und Bussarde. Im äußersten Osten ist ein großer Canyon die Heimat der schwarzen Drachenbrut.\n\nZwergische Prospektoren aus Ironforge kommen, um im Norden zu graben, wo die Ruinen von Uldaman freigelegt wurden. Die Mauern bergen die ersten Hinweise darauf, woher die Zwerge stammen. Die Steingrufttroggs, nach Tausenden von Jahren Schlaf erweckt, schlachteten die Forscher ab und verteidigen die Stadt nun als ihre eigene. Eine große Festung der Dunkeleisenzwerge steht gleich südlich der Ruinen, und ihre Zwerge liegen im Krieg mit den Staubspeier-Ogern und den Drachkin.\n\nIm Nordwesten liegt Kargath, der einzige Außenposten der Horde in Khaz Modan. Kriegshäuptling Thrall schickte seine Orcs dorthin, um ihre abtrünnigen Blackrock-Verwandten im Auge zu behalten.",
		source = "https://warcraft.wiki.gg/wiki/Badlands_(Classic)",
	},
	[1419] = {
		name = "Verwüstete Lande",
		short = "Die Felsen der Verwüsteten Lande waren einst gelbbraun. Sengende Hitze und wilde Energien färbten sie karmesinrot, als das Dunkle Portal zerstört wurde, und das Land ist seitdem eine Wüste geblieben.",
		full = "Die Felsen der Verwüsteten Lande waren einst gelbbraun. Sengende Hitze und wilde Energien färbten sie karmesinrot, als das Dunkle Portal zerstört wurde, und das Land ist seitdem eine Wüste geblieben. Zuvor war es Teil des Schwarzen Morasts, eines dunklen Sumpfgebiets. Die Tage sind heiß und die Nächte bitterkalt. Berge halten jede Feuchtigkeit aus dem Norden ab, kein Fluss fließt hier, und wenn Stürme vom östlichen Meer hereinrollen, rast der Regen vom verdichteten Boden zurück ins Wasser.\n\nUnaufhörlich schlägt der Blitz in den Boden. Basilisken und Skorpione haben die Einöde besiedelt, und Oger streifen durch sie. Ein Überrest der Brennenden Legion unter Lord Kazzak hat hier Zuflucht gefunden.\n\nEine einzige Straße führt von Norden in das Land, und die grimmigen Magier von Burg Nethergarde bewachen sie.",
		source = "https://warcraft.wiki.gg/wiki/Blasted_Lands_(Classic)",
	},
	[1420] = {
		name = "Tirisfal",
		short = "Der Himmel über Tirisfal hängt düster und grün.",
		full = "Der Himmel über Tirisfal hängt düster und grün. Die bewaldeten Hügel hier, an Lordaerons Nordküste, sind vom Fluch der Seuche des Lichkönigs durchtränkt, und die Bäume und das Gestrüpp klammern sich an ihre letzten Fetzen Leben.\n\nUnter König Terenas war dies ein Land stiller Höfe und kleiner Städte, wo Familien über Generationen glücklich lebten. Es war einer der ersten Orte, die fielen, als Prinz Arthas Menethil Lordaeron verheerte. Die Menschen starben, erhoben sich als Sklaven der Geißel, und Massengräber wurden ausgehoben, um den Rest zu fassen. Danach nahmen Fürstin Sylvanas Windrunner und ihre Verlassenen, die ihren freien Willen besitzen, Tirisfal als ihr eigenes Land.\n\nDie Verlassenen haben hier Feinde. Der Scharlachrote Kreuzzug unterhält mehrere Außenposten, darunter das Scharlachrote Kloster, eine Festung seines Glaubens. Diener der Geißel besudeln noch immer die verfallenen Gehöfte und Mühlen.",
		source = "https://warcraft.wiki.gg/wiki/Tirisfal_Glades_(Classic)",
	},
	[1421] = {
		name = "Silberwald",
		short = "Die Kiefern hier sind hoch und haben silbrige Rinde. Sie stehen über grasbewachsenen Hügeln. Vor dem Dritten Krieg hielt die Allianz diesen Wald grün und unversehrt.",
		full = "Die Kiefern hier sind hoch und haben silbrige Rinde. Sie stehen über grasbewachsenen Hügeln. Vor dem Dritten Krieg hielt die Allianz diesen Wald grün und unversehrt. Dann kam die Geißel, brannte die Ernten nieder und tötete die Menschen, und mit dem Fall von Lordaeron war niemand mehr da, der sich um ihn kümmern konnte. Die Bäume wurden blass und krank, und gespenstische Nebel hängen zwischen ihnen. Jetzt ist der Wald still, nur ein Heulen kommt und geht. Verfallene Gehöfte und verlassene Minen liegen über das Land verstreut, Heimat der dunkleren Wesen des Waldes.\n\nDie Verlassenen halten den Norden und führen einen ständigen Guerillakrieg gegen die Fäulnisfell-Gnolle, deren Fell grau und fleckig ist und deren Augen vor Krankheit gelb sind. Ihren Anspruch bestreiten die Magier von Dalaran und die Agenten der Geißel, die einige der verwüsteten Felder halten. Ein paar Menschen klammern sich im Süden ans Leben, bewacht von Magiern, die aus Dalaran geschickt wurden und auch die Seuche und den Fluch der Worgen erforschen. Im Südwesten verwandeln sich die Menschen von Pyrewood unter dem Mond in Worgen, verflucht von Erzmagier Arugal, der sich in den dunklen Türmen von Burg Shadowfang verschanzt. Niemand beherrscht den ganzen Wald.",
		source = "https://warcraft.wiki.gg/wiki/Silverpine_Forest_(Classic)",
	},
	[1422] = {
		name = "Westliche Pestländer",
		short = "Vor der Seuche war dies bewaldetes Ackerland östlich der Hauptstadt von Lordaeron.",
		full = "Vor der Seuche war dies bewaldetes Ackerland östlich der Hauptstadt von Lordaeron. Hearthglen war der Sitz der Regionalregierung, und Andorhal sammelte das Getreide der nördlichen Provinzen und schickte es durch das ganze Königreich.\n\nKel'Thuzad und der Kult der Verdammten wussten, dass Getreide der schnellste Weg für die Seuche war. Sie verseuchten es, und sie stellten vier gewaltige Kessel auf die Felder der vier größten Höfe. Als Lordaeron zusammenbrach, begannen die Wälder zu sterben. Die Kiefern werfen kränkliche braune Nadeln ab, und ihre Stämme schwellen an von Auswüchsen wie Tumoren. Ein rauchgrauer Nebel hängt über dem Boden.\n\nDas Land scheint sich noch zu wehren, mit dem wenigen, was ihm geblieben ist. Der Scharlachrote Kreuzzug hält Hearthglen und schlägt von dort gegen die Geißel zu. Der eine ruhige Ort ist Uthers Grabmal, ein Denkmal für Uther den Lichtbringer.",
		source = "https://warcraft.wiki.gg/wiki/Western_Plaguelands_(Classic)",
	},
	[1423] = {
		name = "Östliche Pestländer",
		short = "Der Boden hier war einst Ackerland, die Dörfer der Östlichen Lande rund um Stratholme verstreut, die zweite Stadt Lordaerons. Nichts davon ist geblieben.",
		full = "Der Boden hier war einst Ackerland, die Dörfer der Östlichen Lande rund um Stratholme verstreut, die zweite Stadt Lordaerons. Nichts davon ist geblieben. Die Erde ist nun braun und krank, die Bäume sind zu Pilzen aufgequollen, und die Luft ist dick von orangefarbenem Nebel.\n\nNach Stratholme kam Prinz Arthas auf der Suche nach dem Ursprung einer Seuche, die bereits die Stadtbewohner befallen hatte. Lord Uther, Meister der Silbernen Hand, weigerte sich, ihn die Stadt säubern zu lassen. Arthas enthob ihn des Kommandos, löste die Silberne Hand an Ort und Stelle auf und ließ die Bewohner Stratholmes selbst über die Klinge springen, statt sie als Diener der Geißel auferstehen zu lassen. Dabei blieb es nicht – er jagte den Schreckenslord Mal'Ganis in den Norden, kehrte als Todesritter zurück und tötete seinen eigenen Vater, um das Königreich Lordaeron zu beenden.\n\nAlexandros Mograine stellte aus den Resten der Silbernen Hand einen Kreuzzug auf, um die Ruinen zurückzuerobern, und nahm Tyrs Hand und halb Stratholme ein, bevor sein Tod seinen Orden in die Argentumdämmerung und den Scharlachroten Kreuzzug spaltete, der diese Felder noch immer hält, endlos gegen die Geißel kämpft und niemanden sonst willkommen heißt.",
		source = "https://warcraft.wiki.gg/wiki/Eastern_Plaguelands_(Classic)",
	},
	[1424] = {
		name = "Vorgebirge von Hillsbrad",
		short = "Der größte Teil von Lordaeron wurde von der Geißel entstellt, doch das Vorgebirge von Hillsbrad sieht noch aus wie das Königreich einst.",
		full = "Der größte Teil von Lordaeron wurde von der Geißel entstellt, doch das Vorgebirge von Hillsbrad sieht noch aus wie das Königreich einst. Die Hügel sind grün, die Wiesen fruchtbar und der Boden reich. Kiefern sprenkeln das Ackerland, und Straßen durchqueren die Weiden von Stadt zu Stadt. Ein Fluss fließt vom Darrowmeresee nach Süden.\n\nTrotzdem ist dies das blutgetränkteste Schlachtfeld in Azeroth. Die erste Schlacht zwischen der Allianz und der Horde im Zweiten Krieg wurde hier geschlagen. Orc-Plünderer fielen über die Küstenstädte her, und Waldtrolle kämpften an ihrer Seite gegen menschliche und hochelfische Verteidiger. Im Dritten Krieg versammelte Thrall die Klans der Orcs, schlich sich dann bei Nacht nach Southshore und stahl seine Schiffe, um die neue Horde über das Meer nach Kalimdor zu tragen.\n\nDie Geißel löschte die Stadt Tarrens Mühle aus. Die Verlassenen nahmen sie als ihren südlichsten Besitz und bedrängen nun die Menschen von Southshore und den Feldern von Hillsbrad, die zur Allianz halten. Gesetzlose des Syndikats, Murlocs und Naga setzen beiden Seiten zu.",
		source = "https://warcraft.wiki.gg/wiki/Hillsbrad_Foothills_(Classic)",
	},
	[1425] = {
		name = "Hinterland",
		short = "Die Wildhammer-Zwerge halten den Westen des Hinterlands, wo sie wilde Greifen zähmen. Die Bindung wurde so stark, dass sie in ihrer Stadt ein riesiges Denkmal in Gestalt eines Greifen errichteten.",
		full = "Die Wildhammer-Zwerge halten den Westen des Hinterlands, wo sie wilde Greifen zähmen. Die Bindung wurde so stark, dass sie in ihrer Stadt ein riesiges Denkmal in Gestalt eines Greifen errichteten. Die Waldtrolle, die dieses Land vor ihnen hielten, Überreste des Imperiums der Amani, nennen die Zwerge Besetzer auf angestammtem Boden und überfallen die Horste.\n\nDie Wildhammer wussten fast nichts von der Horde, als die Orcs im Zweiten Krieg ins Hinterland marschierten. Die Greifenreiter von Than Kurdran Wildhammer begegneten den Eindringlingen aus der Luft, schleuderten sturmgeladene Hämmer von ihren Reittieren und ließen den Kolonnen keine Ruhe. Kriegshäuptling Orgrim Schicksalshammer wollte, dass der Angriff die Allianz hinter ihm herzog, während er Quel'Thalas angriff. Anduin Lothar durchschaute es, schickte die Hälfte seiner Armee zu den Elfen und kämpfte selbst an Kurdrans Seite. Gemeinsam trieben sie die Orcs und ihre Waldtroll-Verbündeten hinaus. Kurdran verpflichtete sein Königreich der Allianz.\n\nVon den drei Trollstämmen hier hat nur der der Revantusk die Seite der Horde gewählt.",
		source = "https://warcraft.wiki.gg/wiki/Hinterlands_(Classic)",
	},
	[1426] = {
		name = "Dun Morogh",
		short = "Tiefer Schnee liegt über Dun Morogh, und seine Berge sind die höchsten der Östlichen Königreiche.",
		full = "Tiefer Schnee liegt über Dun Morogh, und seine Berge sind die höchsten der Östlichen Königreiche. Ihre Gletscher speisen die Flüsse, die die grünen Felder von Khaz Modan wässern, und ihre Gipfel geben den Zwergen Erz ohne Ende. Berge schließen das Land von allen Seiten ein, und zwergische Truppen bewachen die wenigen Pässe.\n\nEistrolle vom Stamm der Frostmane herrschten hier einst, bis zwergische Armeen ihr Reich zerbrachen und sie in die Hügel zurücktrieben. Zwerge und Gnome wurden enge Freunde. Die Zwerge halfen den Gnomen, Gnomeregan zu errichten, und die Gnome teilten ihr Wissen über Maschinen. Als die Orcs im Zweiten Krieg in Khaz Modan einfielen, schlossen sich beide Völker der Allianz an, und zwischen zwergischer Stärke und gnomischem Erfindungsgeist nahmen die Orcs nie eine der beiden Hauptstädte.\n\nJetzt ist Gnomeregan gefallen, und seine Überlebenden suchen in Ironforge Zuflucht. Troggs tauchen überall in der Region auf. Die Frostmane sehen, dass die Armeen von Ironforge mit den Troggs und den Kriegen der Allianz beschäftigt sind, und überfallen die Zwerge häufiger.",
		source = "https://warcraft.wiki.gg/wiki/Dun_Morogh_(Classic)",
	},
	[1427] = {
		name = "Sengende Schlucht",
		short = "Vor mehr als zweihundert Jahren wurde hier der Boden aufgerissen. Zuvor war das Land Teil des Rotkammgebirges.",
		full = "Vor mehr als zweihundert Jahren wurde hier der Boden aufgerissen. Zuvor war das Land Teil des Rotkammgebirges. Zaubererthan Thaurissan von den Dunkeleisenzwergen brauchte etwas, um den Krieg der Drei Hämmer zu seinen Gunsten zu wenden. Er und sieben seiner vertrautesten Zwerge riefen die uralten Mächte an, die unter der Welt schliefen, und was antwortete, war schrecklicher als jeder Albtraum, den sie sich vorgestellt hatten. Es war der Feuerlord Ragnaros. Der Blackrock brach aus dem Gebirgskamm hervor, die Hauptstadt der Dunkeleisenzwerge, Thaurissan, fiel in Schutt, und das Tal im Norden blieb als geschwärzte Kluft zurück. Diese Kluft wurde die Sengende Schlucht.\n\nDie Dunkeleisenzwerge wollten Land für ihre Werke, und die Schlucht war schwach gehalten. Wenige Menschen lebten darin und wenige Soldaten bewachten sie, also überrannte eine große Streitmacht der Dunkeleisenzwerge die Garnisonen der Zwerge und ließ Sklaven die Mitte des Tals aushöhlen. Kriegsgolems und Elementare gehen neben ihnen durch die Schlucht.\n\nNicht jeder Dunkeleisenzwerg blieb beim Klan. Die Thoriumbruderschaft spaltete sich ab und hält ihre eigene Stadt im Norden der Schlucht.",
		source = "https://warcraft.wiki.gg/wiki/Searing_Gorge_(Classic)",
	},
	[1428] = {
		name = "Brennende Steppe",
		short = "Der Himmel über der Brennenden Steppe glüht rot, erleuchtet von Ausbrüchen, die von Zeit zu Zeit aus dem Blackrock kommen.",
		full = "Der Himmel über der Brennenden Steppe glüht rot, erleuchtet von Ausbrüchen, die von Zeit zu Zeit aus dem Blackrock kommen. Lavaströme durchziehen die zerklüfteten Ausläufer, die Erde ist verkohlt, und die Luft bleibt heiß und trocken. Die Straße hier ist der einzige Landweg von Stormwind nach Khaz Modan und Lordaeron. Sie ist viel befahren und sehr gefährlich, und Stormwind hat sie fast aufgegeben.\n\nDas Land war einst Teil des Rotkammgebirges. Im Krieg der Drei Hämmer versuchte der Zaubererthan der Dunkeleisenzwerge, Thaurissan, elementare Diener zu beschwören und rief stattdessen Ragnaros den Feuerlord herbei. Die Berge schmolzen um den Feuerlord, und ein Vulkan erhob sich dort, wo er hindurchkam. Die überlebenden Dunkeleisenzwerge wurden seine Marionetten.\n\nOrcs kamen nach dem Zweiten Krieg hierher, und die Hitze behagt ihnen. Die Blackrockorcs halten eine der wenigen dauerhaften Orc-Siedlungen in Azeroth und achten Thralls Waffenruhe mit der Allianz nicht. Oger der Feuermägen streifen über das Land. Schwarze Drachen unter Nefarian halten die oberen Ebenen der Blackrockspitze, und Dunkeleisenzwerge halten ihre Tiefen, wo das Gerücht sagt, dass Ragnaros noch immer brütet.",
		source = "https://warcraft.wiki.gg/wiki/Burning_Steppes_(Classic)",
	},
	[1429] = {
		name = "Wald von Elwynn",
		short = "Im Ersten Krieg marschierten Tausende Orcs durch den Wald von Elwynn und schlossen Stormwind ein, sodass nur noch das Meer als Fluchtweg blieb.",
		full = "Im Ersten Krieg marschierten Tausende Orcs durch den Wald von Elwynn und schlossen Stormwind ein, sodass nur noch das Meer als Fluchtweg blieb. Ritterchampion Anduin Lothar führte die Ritter von Stormwind in einem Angriff durch die Bäume und überraschte die Nachhut der Orcs. Die Orcs flohen, doch die Erleichterung hielt nicht lange an. Feuer fegte über einen Großteil des Waldes, und bei der zweiten Belagerung fiel Stormwind. Lothar führte die Überlebenden auf Boote nach Lordaeron. Der Klan der Sturmreiter hielt die Ruinen der Stadt eine Zeit lang.\n\nSeither sind die Bäume nachgewachsen, Harthölzer und üppige Lichtungen zwischen rauschenden Flüssen und Seen, und häufiger Regen hält das Ackerland fruchtbar. Holzfäller, Bauern, Fischer und Bergleute bewirtschaften es, und Stormwind käme ohne das, was sie liefern, nicht lange aus. Hier und da liegt noch ein zerbrochenes, verrottendes Katapult der Orcs.\n\nÄrger neuer Art begann in der Hauptstadt. Die Steinmetze bauten Stormwind jahrelang wieder auf und wurden nie bezahlt. Als Gildenmeister Edwin VanCleef forderte, was ihnen zustand, ließen die Adligen, die tief verschuldet waren, die Gilde auflösen. Aufstände folgten, und aus ihnen ging die Bruderschaft der Defias hervor. Ihre Banditen halten Besitzungen im ganzen Wald.",
		source = "https://warcraft.wiki.gg/wiki/Elwynn_Forest_(Classic)",
	},
	[1430] = {
		name = "Gebirgspass der Totenwinde",
		short = "Der Elfenbeinturm von Karazhan steht im Herzen des Passes, der sich durch die Berge im Zentrum von Azeroth schneidet und den Dämmerwald mit den Sümpfen des Elends verbindet.",
		full = "Der Elfenbeinturm von Karazhan steht im Herzen des Passes, der sich durch die Berge im Zentrum von Azeroth schneidet und den Dämmerwald mit den Sümpfen des Elends verbindet. Vor etwa zwanzig Jahren galt der Pass noch als Teil des Rotkammgebirges. Der Turm war die Heimat des dunklen Magiers Medivh, der den Orcs das Dunkle Portal öffnete und im Ersten Krieg gejagt und getötet wurde. Er steht seither verlassen, und seine böse Magie sickert noch immer ins Land.\n\nNichts wächst hier. Die Bäume sind versteinert und kahl, und ein fauler Wind heult durch den zerklüfteten Canyon, der dem Pass seinen Namen gibt. Oger, Dämonen und Untote streifen durch das Innere, dazu ein paar Menschen vom fahrenden Volk. Aasvögel sind die einzige Tierwelt.\n\nAdlige aus Dunkelhain kamen, um dem Verfall nachzugehen, und keiner, der den Turm betrat, kam wieder heraus. Reisende sagen, eine neue Macht habe ihn für sich beansprucht, und die Oger und Dämonen gehorchten ihr. Die Dunklen Reiter, eine geheimnisvolle Bande, die im Dämmerwald gesehen wird, stammen bekanntermaßen aus diesem Pass.",
		source = "https://warcraft.wiki.gg/wiki/Deadwind_Pass_(Classic)",
	},
	[1431] = {
		name = "Dämmerwald",
		short = "Der Dämmerwald war einst der südliche Teil des Waldes von Elwynn, ein Lehen von Stormwind namens Schattenwald. Zwei ansehnliche Städte standen zwischen seinen Höfen.",
		full = "Der Dämmerwald war einst der südliche Teil des Waldes von Elwynn, ein Lehen von Stormwind namens Schattenwald. Zwei ansehnliche Städte standen zwischen seinen Höfen. Jetzt hängt ein schwarzer Nebel unter den Bäumen, die Stämme sind knorrig geworden, und die Nacht weicht nicht.\n\nDie Dunkelheit hängt mit der Sense von Elune zusammen, einem Artefakt, das die Nachtelfe Velinde Sternensang in diese Wälder trug. Mit dem Nebel kamen Worgen. Die Toten steigen aus den Friedhöfen, und Oger sind aus dem Gebirgspass der Totenwinde hereingedrängt. Der Dämmerwald zählt noch zur Allianz, doch Stormwind ist weit weg und hat den Wald sich selbst überlassen. Die Menschen, die bleiben, klammern sich an ihren Besitz und geben ihn nicht auf. Ihre Miliz, die Nachtwache, patrouilliert auf den Straßen und schützt Dunkelhain vor Skelettkriegern, Ghulen, Worgen und Männern der Defias.\n\nIn seiner Mitte liegt ein uralter Vulkankrater, längst erloschen und nun voller Leben, mit einem Zwielicht, das sanfter ist als die Dunkelheit draußen. Anderswo liegen verlassene Gehöfte und der Friedhof von Rabenflucht, der die Gräber all derer birgt, die seit Einbruch der Dunkelheit von Bestien und Untoten getötet wurden.",
		source = "https://warcraft.wiki.gg/wiki/Duskwood_(Classic)",
	},
	[1432] = {
		name = "Loch Modan",
		short = "Graue Berge erheben sich auf allen Seiten von Loch Modan, ihre Hügel leicht mit Kiefern und Birken bewaldet.",
		full = "Graue Berge erheben sich auf allen Seiten von Loch Modan, ihre Hügel leicht mit Kiefern und Birken bewaldet. Der Stonewroughtdamm hält den See an seinem Platz, ein Werk zwergischer Baukunst, das auf Azeroth nicht seinesgleichen hat.\n\nSo ruhig er aussieht, hat der See Krieg gesehen. Im Zweiten Krieg überrannten die Orcs der Horde dieses Land und stellten sich den Verteidigern der Allianz. Die Zwerge von Ironforge hielten stand, und als der Krieg endete, holten sie das Land zurück. Zerbrochene Katapulte und Ballisten liegen noch auf dem Grund des Sees und auf seinen Inseln, ein deutlicher Beweis jener Kämpfe.\n\nDer Frieden ist nicht zurückgekehrt. Die Grabungen der Zwerge brachen Höhlen unter der Erde auf, und die Troggs, die sie ausgruben, haben sich in den Bergen niedergelassen. Sie bauen grobe Lager und Höhlen, aus denen sie auf Reisende losgehen. Feindliche Kobolde, wilde Tiere und die Oger im Nordosten steigern die Gefahr.",
		source = "https://warcraft.wiki.gg/wiki/Loch_Modan_(Classic)",
	},
	[1433] = {
		name = "Rotkammgebirge",
		short = "Ulmen ragen über schnellen Flüssen im Rotkammgebirge auf, und das Land steigt stetig zu den Gipfeln an. Das Gebirge liegt östlich des Waldes von Elwynn und südlich der Brennenden Steppe.",
		full = "Ulmen ragen über schnellen Flüssen im Rotkammgebirge auf, und das Land steigt stetig zu den Gipfeln an. Das Gebirge liegt östlich des Waldes von Elwynn und südlich der Brennenden Steppe. Diese Hügel stehen unter dem Schutz von Stormwind, auch wenn sie seit dem Zweiten Krieg dem Namen nach unabhängig sind. Die Menschen sind ruhig und zufrieden. Sie schicken Stormwind Holz aus den Wäldern, Fisch aus dem See und Feldfrüchte, und Rotkamm ist eine der letzten friedlichen Regionen in Azeroth.\n\nDer Frieden ist unvollkommen. Eine Streitmacht der Blackrockorcs kam aus der Brennenden Steppe herab und hält die Burg Steinwacht. Gnolle und weitere Blackrockorcs bedrängen die Stadt Seenhain aus den umliegenden Hügeln. Die Straße von der Kreuzung bei Drei Ecken zur Burg wird von Drachenwelpen, Gnollen, Murlocs und wilden Tieren gehalten.\n\nDie Oberfläche des Immerruhsees wirkt ruhig. Unter ihm leben Murlocs, und die Leute sprechen noch immer von einem Seeungeheuer im tiefen Wasser.",
		source = "https://warcraft.wiki.gg/wiki/Redridge_Mountains_(Classic)",
	},
	[1434] = {
		name = "Schlingendorntal",
		short = "Über Zeitalter hinweg herrschten die Dschungeltrolle der Gurubashi über dieses Land, und ihre Steinstädte lagen darüber verstreut. Das Imperium wurde grausam.",
		full = "Über Zeitalter hinweg herrschten die Dschungeltrolle der Gurubashi über dieses Land, und ihre Steinstädte lagen darüber verstreut. Das Imperium wurde grausam. Seine Priester opferten Trolle anderer Stämme Hakkar dem Seelenschinder, einem Blutgott, und ein langer Bürgerkrieg spaltete die Stämme für immer. Die Darkspear gingen ihren eigenen Weg. Die übrigen blieben im Tal und bekämpfen einander seither.\n\nDie Städte fielen, und der Dschungel schloss sich über ihnen. Die Blutskalpe halten den Nordwesten und die Schädelspalter den Osten, jeder Stamm lebt zwischen den Ruinen und vertreibt jeden, der sich nähert. Zul'Gurub, einst die Hauptstadt, liegt in einem Tal im Nordosten. Naga jagen an der Küste, und die Schlingdornen, die dem Tal seinen Namen geben, verfilzen jeden Pfad ins Landesinnere.\n\nImmer wieder kommen Fremde ins Land. Goblins des Steamwheedle-Kartells betreiben einen Hafen an der Südküste, und Piraten legen dort an. Im Norden hat die Expedition von Oberst Conrad Kurzen ein Lager zwischen den Bäumen errichtet, wo seine Männer miteinander im Krieg liegen. Die Trolle beobachten das alles, und ihr Wunsch, das Land von Fremden zu säubern, wächst.",
		source = "https://warcraft.wiki.gg/wiki/Stranglethorn_Vale_(Classic)",
	},
	[1435] = {
		name = "Sümpfe des Elends",
		short = "Die Sümpfe des Elends waren einst die nördliche Hälfte eines gewaltigen Sumpflandes namens Schwarzer Morast, und in der südlichen Hälfte öffnete sich das Dunkle Portal.",
		full = "Die Sümpfe des Elends waren einst die nördliche Hälfte eines gewaltigen Sumpflandes namens Schwarzer Morast, und in der südlichen Hälfte öffnete sich das Dunkle Portal. Die Orcs der Alten Horde kamen hindurch und errichteten zwei Siedlungen und einen Außenposten im Morast. Von dort aus führten sie den Ersten Krieg. Als das Portal am Ende des Zweiten Krieges einstürzte, wurde die südliche Hälfte zu den kargen Verwüsteten Landen. Die nördliche Hälfte behielt ihr Wasser und ihren Namen.\n\nDies ist ein träges Land aus saugenden Mooren und weinenden Bäumen. Meerwasser sickert in das Moor, sodass die Tümpel brackig sind und Krokilisken in ihnen gedeihen. Salz verkrustet die umgestürzten Stämme und die Felsen. Sumpfbestien waten durch das Innere, und Sumpfjaguare jagen entlang der Ufer. Die einzige Straße ragt nur eine Handbreit über das Wasser und wurde mit großer Mühe gebaut, damit Reisende hindurchkommen.\n\nEinige Draenei kamen auf der Suche nach einem neuen Leben durch das Dunkle Portal und ließen sich hier nieder. Heimweh trieb die meisten von ihnen in den Wahnsinn, und sie greifen alle auf Sicht an. Weit weg von Stormwind hat die Horde eine eigene Kolonie errichtet. Grüne Drachen patrouillieren im Sumpf auf den Befehl von Ysera der Träumerin und bewachen einen zerstörten Trolltempel, der unter seinem größten Moor liegt.",
		source = "https://warcraft.wiki.gg/wiki/Swamp_of_Sorrows_(Classic)",
	},
	[1436] = {
		name = "Westfall",
		short = "Der Wind fegt über die Felder von Westfall, und nichts hält ihn auf. Dies war die Kornkammer von Stormwind, sanftes Weideland und Ackerland, und jetzt ist das Gras gelb und dünn, und Aasvögel füllen die Felder.",
		full = "Der Wind fegt über die Felder von Westfall, und nichts hält ihn auf. Dies war die Kornkammer von Stormwind, sanftes Weideland und Ackerland, und jetzt ist das Gras gelb und dünn, und Aasvögel füllen die Felder.\n\nDie Steinmetzgilde baute Stormwind nach dem Zweiten Krieg wieder auf und wurde nie dafür bezahlt. Ihr Gildenmeister Edwin VanCleef führte die Steinmetze hinaus aufs Land, und dort wurden sie zur Bruderschaft der Defias. Die Bauern waren von den Überfällen der Orcs noch erschüttert und leisteten wenig Widerstand. Die Bruderschaft vertrieb viele von ihnen und heuerte Flusspfoten-Gnolle an, das Land zu halten. Ihre Männer brannten die Felder nieder und salzten die Erde, und Goblins, die sich ihnen anschlossen, bauten Erntegolems, die jeden jagen, der allein durch die brachliegenden Reihen geht.\n\nStormwind, knapp an Gold und Soldaten, überlässt die Region sich selbst. Gryan Stoutmantle gründete die Volksmiliz, eine Freiwilligentruppe, die hier gegen die Bruderschaft eine letzte Festung hält.",
		source = "https://warcraft.wiki.gg/wiki/Westfall_(Classic)",
	},
	[1437] = {
		name = "Sumpfland",
		short = "Nebel hängt tief über dem Sumpfland, und der Himmel ist von einem Ende des Landes bis zum anderen ein flaches Grau.",
		full = "Nebel hängt tief über dem Sumpfland, und der Himmel ist von einem Ende des Landes bis zum anderen ein flaches Grau. Kleine Flüsse, Seen und Tümpel durchziehen den Boden, Berge schließen das Land auf drei Seiten ein, und im Westen liegt das Meer offen. Überall im Land standen einst Zwergenfestungen. Der Krieg hat sie zu Trümmern gemacht, und heute beherrschen Murlocs, wilde Tiere und abtrünnige Orcs das Land.\n\nIm Zweiten Krieg nahm der Dragonmawklan die Festung Grim Batol in den Bergen im Osten ein. Die Orcs und ihre Drachen fraßen das Wild bis auf wenige Tiere weg, und auch die Pflanzen litten darunter.\n\nDie Dragonmaw verloren ihren Halt, als die roten Drachen, die sie versklavt hatten, sich befreiten und ihre Lager und Katapulte niederbrannten. Die Überlebenden flohen nach Süden in die Berge, wo sie noch immer leben. Der Hafen von Menethil auf einer kleinen Insel in der Baradinbucht ist der einzige Stützpunkt der Allianz im Sumpfland.",
		source = "https://warcraft.wiki.gg/wiki/Wetlands_(Classic)",
	},
	[1438] = {
		name = "Teldrassil",
		short = "Nach dem Dritten Krieg verschwand Malfurion Stormrage im Smaragdgrünen Traum, und der Erzdruide Fandral Staghelm übernahm die Führung der Nachtelfendruiden.",
		full = "Nach dem Dritten Krieg verschwand Malfurion Stormrage im Smaragdgrünen Traum, und der Erzdruide Fandral Staghelm übernahm die Führung der Nachtelfendruiden. Fandral sagte dem Zirkel der Uralten, die Zeit sei gekommen, einen neuen Weltenbaum wachsen zu lassen und die Unsterblichkeit zurückzugewinnen, die die Nachtelfen verloren hatten. Der Zirkel und die Druiden vereinten ihre Kräfte, und ein gewaltiger Baum erhob sich aus dem Verhüllten Meer. Sie nannten ihn Teldrassil, was auf Darnassisch Krone der Erde bedeutet.\n\nDie Nachtelfen machten ihr Zuhause in seinen Ästen. Erde hat sich auf den großen Ästen gesammelt, und ein dämmriger Wald aus mächtigen Bäumen, Bächen und Seen bedeckt sie, mit der Stadt Darnassus an der Westseite. Doch Nozdormu, dessen Segen auf dem ersten Weltenbaum den Nachtelfen ihr langes Leben schenkte, nannte den Wunsch anmaßend und weigerte sich, diesen Baum zu segnen. Sein Wachstum ist fehlerhaft, und die Unsterblichkeit kam nie.\n\nNun hat sich eine finstere Macht über das Land gelegt. Furbolgs und Grells sind wahnsinnig geworden, und Satyrn sind zwischen den Bäumen aufgetaucht. Die großen Schildkröten und Drescher des umgebenden Meeres schwimmen davon, um an den Küsten der Dunkelküste zu stranden und zu sterben. Die Quelle der Verderbnis ist noch ein Rätsel, und sie hält die Schildwachen und die Druiden voll beschäftigt.",
		source = "https://warcraft.wiki.gg/wiki/Teldrassil_(Classic)",
	},
	[1439] = {
		name = "Dunkelküste",
		short = "Der Name kommt vom Nebel. Ein grauer Dunst liegt an den meisten Tagen über dieser Küste, und Regen und Wind peitschen die felsigen Strände.",
		full = "Der Name kommt vom Nebel. Ein grauer Dunst liegt an den meisten Tagen über dieser Küste, und Regen und Wind peitschen die felsigen Strände.\n\nVor zehntausend Jahren lag das Land weiter landeinwärts, und die Nachtelfen errichteten hier große Städte, darunter Ameth'Aran und Bashal'Aran. Sie fielen, als der erste Brunnen der Ewigkeit zerschmettert wurde, und die Große Zerschlagung schnitt eine neue Küstenlinie durch die Region. Ihre Ruinen stehen noch auf den Klippen, und Geschichten erzählen, dass Murlocs und Naga sie langsam übernehmen.\n\nDie wenigen Nachtelfen, die hier lebten, gingen im Dritten Krieg fort. Danach kehrten einige wenige zurück, um den Hafen wiederzubeleben, und räumten die Ruinen weg, die sie nicht wiederherstellen konnten. Fandral Staghelm führte außerdem Druiden an diese Küste, und von ihr aus pflanzten sie Teldrassil.\n\nDie Berge im Osten halten den größten Teil der Verderbnis des Teufelswalds fern, doch die Flüsse tragen sie trotzdem herab. Sie färbt das Land grau und vergiftet die Tiere, und die Furbolgs, die sie erreicht, verfallen in eine Wut, die nicht mehr weicht.",
		source = "https://warcraft.wiki.gg/wiki/Darkshore_(Classic)",
	},
	[1440] = {
		name = "Ashenvale",
		short = "Regen fällt in Ashenvale fast ohne Pause, doch die Bäume sind so alt und dicht, dass nur Rinnsale den Boden erreichen.",
		full = "Regen fällt in Ashenvale fast ohne Pause, doch die Bäume sind so alt und dicht, dass nur Rinnsale den Boden erreichen. Die Nachtelfen jagten nach der Großen Zerschlagung in diesen Wäldern und bauten nie eine Stadt in ihnen. Die Schildwachen und die Urtume, lebende Bäume, die als Wächter dienen, beschützen den Wald und schlagen jeden nieder, der einen lebenden Baum fällt.\n\nDie Horde kam im Dritten Krieg. Goblins unter Neeloc Greedyfingers begannen, die Bäume zu fällen, und der Kriegshymnenklan folgte. Grommash Höllschrei vertrieb die Furbolgs und die Schildwachen und gewann die Hilfe der Goblins. Cenarius kam, um die gefällten Bäume wiederherzustellen. Die Herren der Brennenden Legion hatten Grommash getäuscht, und er tötete den Halbgott. Dann fielen Archimondes Höllenbestien brennend vom Himmel, und Untote und Dämonen strömten am Ostrand des Waldes herein und marschierten auf den Berg Hyjal zu. Als Tyrande Whisperwind Malfurion Stormrage aus dem Smaragdgrünen Traum weckte, sah der Erzdruide erschüttert, dass der Wald unter Teufelsfeuer lag und an der Fäulnis erstickte.\n\nJetzt halten die Nachtelfen Astranaar und ihre anderen Zufluchten im Westen. Die Horde hält den Osten vom Splintertreeposten aus und fällt Holz in den Holzfällerlagern des Kriegshymnenklans. Dämonen der Legion verweilen noch im Wald, und Satyrn haben alte Elfenruinen für sich genommen.",
		source = "https://warcraft.wiki.gg/wiki/Ashenvale_(Classic)",
	},
	[1441] = {
		name = "Tausend Nadeln",
		short = "Man glaubt, dass einst ein Fluss diesen Canyon schnitt und hohe Sandsteinsäulen darin stehen ließ, mit grünem Wald an seinen Ufern. Dann riss die Zerschlagung die Welt auseinander.",
		full = "Man glaubt, dass einst ein Fluss diesen Canyon schnitt und hohe Sandsteinsäulen darin stehen ließ, mit grünem Wald an seinen Ufern. Dann riss die Zerschlagung die Welt auseinander. Der Fluss änderte seinen Lauf, die Bäume starben, und der Boden wurde zu orangefarbenem Staub. Der See im Osten trocknete zu einer riesigen Salzfläche aus, die unter dem Meeresspiegel liegt. Ein alkalischer See in ihrer Mitte enthält zehnmal so viel Salz wie jeder Ozean. Falfindel Waywarder aus Thalanaar vermutet, dass irgendeine Art dunkler Magie das Land verdorren ließ. Trotz des kargen Bodens kann der Sonnenaufgang, vom Freiwindposten oder von den Mesas rund um den Düsterwolkengipfel aus gesehen, prächtig sein.\n\nDutzende der Steinsäulen erheben sich noch immer wie ein Wald vom Canyonboden. Brücken überspannen die Spitzen vieler von ihnen, sodass ein Reisender den Canyon überqueren kann, ohne den Kriegstrupps der Zentauren zu begegnen, die darunter patrouillieren. Raubvögel greifen die Unvorsichtigen auf diesen Brücken an, und die größeren haben sie manchmal zerstört.\n\nDie Canyons sind seit Langem Taurenland. Um den Zentaurenstämmen auszuweichen, die sie fast ausgelöscht hätten, leben die Tauren auf den Spitzen der hohen Mesas. Jetzt kämpfen sie mit Hilfe der Horde gegen die Zentauren und gegen den fanatischen Stamm der Grimmtotem zurück.",
		source = "https://warcraft.wiki.gg/wiki/Thousand_Needles_(Classic)",
	},
	[1442] = {
		name = "Steinkrallengebirge",
		short = "Das Steinkrallengebirge hat seinen heiligsten Boden auf dem größten Gipfel der Bergkette. Nachtelfen betreuen dort oben einen Grabhügel und eine Lichtung und stehen dort mit den Geistern der Natur in Verbindung.",
		full = "Das Steinkrallengebirge hat seinen heiligsten Boden auf dem größten Gipfel der Bergkette. Nachtelfen betreuen dort oben einen Grabhügel und eine Lichtung und stehen dort mit den Geistern der Natur in Verbindung. Auch die Tauren halten den Gipfel für heilig, weil dort einst das unsterbliche Orakel lebte und die Fäden des Schicksals betrachtete, wie die Erdenmutter sie webte. Die Taurenlegende sagt, dass der erste ihres Volkes, der sich in diesen Bergen niederließ, große flammende Totems auf die höchsten Klippen trug und für An'she Feuer entzündete, um die Dunkelheit zu vertreiben, die am Stein haftete.\n\nElune segnete in uralter Zeit einen Quell der Gesundheit in diesen Bergen. Im Dritten Krieg fingen Harpyien die Wyvern ein, die in der Nähe nisteten, und beschmutzten das Wasser des Quells. Thrall zog mit Cairne Bloodhoof und seinen Tauren gegen sie. Sie zerschlugen eine Zentaurenbande, um eine Glyphe der Läuterung zu erringen, und reinigten den Quell damit, und die befreiten Wyvern trugen sie zum Gipfel hinauf.\n\nWeiter unten ist das Land kahlgeschlagen. Goblins der Venture Co. haben fast jeden Baum in der Scherwindklippe gefällt, die Luft mit Ruß gefüllt und das Wasser mit Öl und Abfall verdorben, zur Wut der Orcs und Tauren. Die Geister der Berge schrien dagegen auf, so laut, dass noch die Schamanen im fernen Orgrimmar es hörten.",
		source = "https://warcraft.wiki.gg/wiki/Stonetalon_Mountains_(Classic)",
	},
	[1443] = {
		name = "Desolace",
		short = "Taurenschamanen kamen einst in ein grünes Grasland, angezogen von schwachen Regungen in der Erde. Sie glaubten, die Erdenmutter selbst schlafe unter den Wiesen, und jahrzehntelang riefen sie nach ihr.",
		full = "Taurenschamanen kamen einst in ein grünes Grasland, angezogen von schwachen Regungen in der Erde. Sie glaubten, die Erdenmutter selbst schlafe unter den Wiesen, und jahrzehntelang riefen sie nach ihr. Schließlich erwachte jemand. Es war Prinzessin Theradras, Tochter von Therazane der Steinmutter. Schwach von ihrem langen Schlaf, streckte sie sich aus und trank das Leben aus dem Land um sich herum. Die Tauren nannten den toten Boden Desolace.\n\nZaetar, ein Sohn des Waldfürsten Cenarius, kam, um sie zu binden. Er verliebte sich stattdessen in sie, und sie liebte ihn zurück. Ihre Kinder waren die Zentauren, und das Erste, was sie taten, war, ihren Vater zu ermorden. Sie breiteten sich über das Land aus, vertrieben die Tauren und begannen einen Krieg zwischen den beiden Völkern, der Jahrhunderte währte.\n\nNun ist Desolace eine graue, felsige Wüste aus Knochen und toten Bäumen, unter schwarzem Himmel und beständigem Wind. Vier Zentaurenstämme, jeder unter seinem eigenen Khan, bekämpfen einander so heftig wie Fremde. Die Horde und die Allianz haben hier beide Lager errichtet, und der Kult der Burning Blade hat Portale geöffnet, um Dämonen ins Land zu bringen.",
		source = "https://warcraft.wiki.gg/wiki/Desolace_(Classic)",
	},
	[1444] = {
		name = "Feralas",
		short = "Wo das Land ringsum karg ist, ist Feralas ein Dschungel aus riesigen, uralten Bäumen. Die Nachtelfen breiteten einst ihre Macht über diesen Wald aus, und ihre Ruinen liegen überall, überwuchert von Wurzeln und Ranken.",
		full = "Wo das Land ringsum karg ist, ist Feralas ein Dschungel aus riesigen, uralten Bäumen. Die Nachtelfen breiteten einst ihre Macht über diesen Wald aus, und ihre Ruinen liegen überall, überwuchert von Wurzeln und Ranken. Die größte ist die Stadt, die heute Düsterbruch heißt.\n\nDie Oger der Gordunni haben sich zu Herren der Ruinen und eines großen Teils des Waldes gemacht, und sie verderben, was sie besetzt halten. Sie haben ganze Streifen Wald gerodet, und ihre Verderbnis liegt auf dem Land. Raubtrupps brennen Dörfer nieder und überfallen Reisende in den südlichen Wäldern. Die Horde fürchtet das Wachstum des Klans, und Belgrom Felshammer in Orgrimmar hat Kämpfer aufgerufen, um ihn zurückzudrängen.\n\nTauren der Grimmtotem leben verstreut in den Wäldern, gejagt von Agenten der Horde auf Belgroms Befehl. Naga drängen sich auf den Inseln vor der Westküste, und neuerdings hat man im Wald Silithidenbaue gefunden. Einer der vier Großen Bäume, die sich zum Smaragdgrünen Traum öffnen, wächst hier, bewacht von den grünen Drachen.",
		source = "https://warcraft.wiki.gg/wiki/Feralas_(Classic)",
	},
	[1445] = {
		name = "Marschen von Dustwallow",
		short = "Die Marschen von Dustwallow waren einst eine hohe Ebene aus hohem Gras, abgeweidet von großen Herden.",
		full = "Die Marschen von Dustwallow waren einst eine hohe Ebene aus hohem Gras, abgeweidet von großen Herden. Die Zerschlagung schlug sie zu einem Tal nieder, und Wasser sickerte aus dem Untergrund herauf und hält sie seither nass. Schmale Ufer aus glitschigem Schlamm trennen stehende Tümpel und algenverstopfte Rinnen. Schwimmende Pflanzen schließen sich über dem, was wie fester Boden aussieht, und wer hindurchtritt, sitzt im brackigen Wasser darunter fest. Mücken surren in der Luft, und Bäume tauchen ihre Wedel ins Wasser. Krokilisken, Raptoren und Spinnen lauern in jedem Tümpel und jedem Busch. Im Süden nisten schwarze Drachen in solcher Zahl, dass das Land der Drachensumpf genannt wird.\n\nWilde Tiere hatten die Marschen bis zum Dritten Krieg für sich allein. Nach der Schlacht am Berg Hyjal führte Lady Jaina Proudmoore ihr Volk an die Ostküste und errichtete Theramore auf einer felsigen Insel. Ihr Vater, Großadmiral Daelin Proudmoore, führte die Flotte von Kul Tiras gegen die Horde, und die Marschen wurden zum Schlachtfeld.\n\nWeder die Horde noch die Allianz halten heute viel davon. Theramores Mauern glänzen, doch sie halten vor allem die Allianz im Innern. Ein paar Türme und Kontrollposten stehen an der Straße zum Brachland, und die Garnison wird dünner, weil Soldaten desertieren, aus Gründen, die niemand erklären kann. Der einzige Stützpunkt der Horde ist das Dorf Brackenwall im Nordwesten, wo die Oger der Stonemaul unter Oberanführer Mok'Morokk leben. Ein Waffenstillstand gilt auf dem Papier, während Infiltratoren der Allianz und Spione der Horde im Geheimen arbeiten, und einige von ihnen verschwinden.",
		source = "https://warcraft.wiki.gg/wiki/Dustwallow_Marsh_(Classic)",
	},
	[1446] = {
		name = "Tanaris",
		short = "Nozdormu, der Drache der Zeit, soll dieses Land schon zu seiner Heimat gemacht haben, bevor irgendwer die Jahre zählte. Die Hitze und die endlosen Meilen leeren Sandes sagten ihm zu.",
		full = "Nozdormu, der Drache der Zeit, soll dieses Land schon zu seiner Heimat gemacht haben, bevor irgendwer die Jahre zählte. Die Hitze und die endlosen Meilen leeren Sandes sagten ihm zu. Tanaris ist seit Äonen ein endloses Meer aus Sand.\n\nDas Land besteht aus sanften Dünen unter einem wolkenlosen Himmel, mit Sandstürmen, die schnell aufziehen. Der Süden ist rauer, mit Bergen über Höhlennetzen, die tief hinabreichen und kaum erforscht sind. Hyänen, Skorpide, Basilisken und Silithiden sind draußen im Sand häufig, und Drachen reiten manchmal auf der heißen Luft über ihnen. Die Silithiden bauen seit langer Zeit Baue in den abgelegenen Gegenden. Auch die Titanen haben hier eine Stätte hinterlassen, die uralte Stadt Uldum.\n\nDie Goblins des Steamwheedle-Kartells haben Gadgetzan und Steamwheedle in dieser Wüste gebaut. Näher an ihrer Heimat kommen sie auf den Kontinenten nicht.",
		source = "https://warcraft.wiki.gg/wiki/Tanaris_(Classic)",
	},
	[1447] = {
		name = "Azshara",
		short = "Der Herbst verlässt Azshara nie.",
		full = "Der Herbst verlässt Azshara nie. Die Bäume entlang der Küste brennen orange und rot, und dahinter fallen große Klippen zu elfenbeinfarbenen Stränden ab und zu einem flachen Meer, das von Zacken aus schroffem Fels durchbrochen wird.\n\nVor zehntausend Jahren war diese Küste Teil von Zin-Azshari, der Hauptstadt der Nachtelfen. Als die Dämonen aus der Welt vertrieben wurden, riss die Große Zerschlagung das Land auseinander, und das Meer strömte ein. Der größte Teil der Stadt ertrank. Ein paar zerlumpte Gebäude hocken noch auf den Klippen und blicken auf Ruinen zwischen den Korallen hinab. Die Nachtelfen, die es überlebten, nannten die zerbrochene Küste nach Azshara, ihrer Königin, die der Einfluss der Dämonen in den Wahnsinn getrieben hatte, und sie nennen sie verflucht.\n\nIm Dritten Krieg zog Illidan Stormrage mit seinen Naga und Satyrn hindurch und zerstörte die nachtelfischen Häfen an dieser Küste, damit ihm niemand folgen konnte. Maiev Schattensang und ihre Wächterinnen folgten seiner Spur und mussten die leidenden Kreaturen niederstrecken, die er zurückließ. Manche Nachtelfen sagen, dass Dämonen noch unter dem glitzernden Wasser lauern. Andere sagen, die Königin habe das Ertrinken überlebt und sei in ein abscheuliches Geschöpf des Meeres verwandelt worden.",
		source = "https://warcraft.wiki.gg/wiki/Azshara_(Classic)",
	},
	[1448] = {
		name = "Teufelswald",
		short = "Der Teufelswald war einst der nördliche Wald von Ashenvale, von den Nachtelfen gepflegt und von Cenarius behütet. Bäche zogen durch stille Wiesen, und Singvögel füllten den Wald.",
		full = "Der Teufelswald war einst der nördliche Wald von Ashenvale, von den Nachtelfen gepflegt und von Cenarius behütet. Bäche zogen durch stille Wiesen, und Singvögel füllten den Wald. Dann drängte die Brennende Legion auf den Berg Hyjal zu. Archimonde befahl, den Wald zu verderben, um die Nachtelfen zu schwächen, die ihn verteidigten, und der Schreckenslord Tichondrius führte den Befehl mit dem Schädel des Gul'dan aus, einem Relikt der Hexenmeister. Illidan Stormrage wagte sich in den Wald, besiegte Tichondrius und nahm den Schädel an sich. Sein Bruder Malfurion verbannte ihn dafür, dass er dämonische Macht benutzt hatte, doch die Verderbnis blieb im Land.\n\nAuf den Wiesen wächst jetzt nichts mehr. Die Urtume, die den Wald einst bewachten, streifen blind umher, ihre verdrehten Glieder bluten Teufelsgift, und sie richten ihre schlimmste Wut gegen alles, was nach einem Elfen aussieht. Pflanzenfresser verschmähen die verfluchte Vegetation, deshalb fressen die Tiere einander und sind toll vor Wut. Von der Verderbnis ruinierte Furbolgs wandern durch die Bäume, und Satyrn versammeln sich an verseuchten Mondbrunnen. In Jaedenar hält der Schattenrat seine Stellung, und Druiden und Hexenmeister tauschen Blitze arkanen Feuers. Die Nachtelfen schämen sich, dass sie diesen Wald im Stich gelassen haben, und sie haben nicht aufgehört zu versuchen, ihn zu heilen.",
		source = "https://warcraft.wiki.gg/wiki/Felwood_(Classic)",
	},
	[1449] = {
		name = "Un'Goro-Krater",
		short = "Die Qiraji nennen diesen Krater das Land der Götter.",
		full = "Die Qiraji nennen diesen Krater das Land der Götter. Im Krieg der Sandstürme wurde das nachtelfische Heer durch ihn zurückgedrängt, bis an die Grenzen der Wüste Tanaris, und dort hinderte etwas in Un'Goro die Qiraji daran, das Land zu nehmen. Was es war, ist nicht bekannt.\n\nDrei Wüsten drängen sich um den Krater und schneiden ihn fast ganz vom Rest der Welt ab. Trotzdem füllt ihn ein dichter Dschungel aus exotischen Pflanzen und noch seltsameren Tieren. Friedliche Erdelementare gehen zwischen tobenden Teufelssauriern umher. Ein Vulkan erhebt sich in der Mitte, wo Feuerelementare umherstreifen, und seltsame Kristalle sprenkeln den Boden. Wenige kennen ihren Zweck, doch einige der Wissenschaftler, die hier lagern, erforschen sie.\n\nAuf den Graten darüber stehen Pylonen, und genaues Hinsehen hat sie nicht erklärt. Geologin Larksbane hat herausgefunden, dass der Krater eine Verbindung zu den Titanen hat. Darüber hinaus ist der Krater älter als alle lebende Erinnerung.",
		source = "https://warcraft.wiki.gg/wiki/Un'Goro_Crater_(Classic)",
	},
	[1450] = {
		name = "Moonglade",
		short = "Moonglade liegt eingebettet in einem Ring hoher Berge, ein verborgenes Tal aus Hügeln und altem Wald, das die Verderbnis nie berührt hat.",
		full = "Moonglade liegt eingebettet in einem Ring hoher Berge, ein verborgenes Tal aus Hügeln und altem Wald, das die Verderbnis nie berührt hat. Zahllose Hügel erheben sich zwischen den Bäumen, und unter ihnen liegen die Sanktums vergangener Druiden.\n\nCenarius wohnte einst hier. Im Krieg der Ahnen, als die Zahl der Brennenden Legion anschwoll, erkannte Malfurion Stormrage, dass die Nachtelfen allein nicht siegen konnten. Er brachte Tyrande Whisperwind und seinen Bruder Illidan in die heilige Stille des Tals, um Cenarius um Hilfe anzuflehen. Der Halbgott antwortete. Nach der Großen Zerschlagung kamen die Bewahrer des Hains und die Dryaden, die hier Zuflucht gefunden hatten, aus Moonglade hervor und zogen in die Welt.\n\nEinige Jahre nach dem Dritten Krieg wurde Moonglade allen Völkern der Druiden geöffnet, und Bewahrer Remulos wurde sein Hüter. Tauren und Nachtelfen leben Seite an Seite, verbunden durch ihre gemeinsame Ehrfurcht vor der Natur. Die Aufseher von Moonglade dulden keine Streitigkeiten zwischen ihnen. Der Halbgott Omen, im Krieg der Ahnen in den Wahnsinn getrieben, schläft in der Tiefe des mittleren Sees und regt sich jedes Jahr um das Mondfest.",
		source = "https://warcraft.wiki.gg/wiki/Moonglade",
	},
	[1451] = {
		name = "Silithus",
		short = "Sand und zerbrochener Fels bedecken die südwestliche Ecke von Kalimdor, und das Einzige, was sich aus der Einöde erhebt, sind die riesigen Baue der Silithiden.",
		full = "Sand und zerbrochener Fels bedecken die südwestliche Ecke von Kalimdor, und das Einzige, was sich aus der Einöde erhebt, sind die riesigen Baue der Silithiden.\n\nEin Teil des alten Aqir-Reiches liegt hier, das Land, das Ahn'Qiraj heißt. Es ist heute unbewohnt, und sein zentraler Tempel ist versiegelt. Am Ende des Krieges der Sandstürme sperrten die Nachtelfen und die Bronzedrachen die Qiraji hinter dem Skarabäuswall ein, und die Wüste hält dieses Gefängnis seit Tausenden von Jahren. Die Diener der Qiraji, die Silithiden, wurden nicht eingesperrt. Sie haben sich vermehrt und im südlichen Kalimdor ausgebreitet.\n\nDer Zirkel des Cenarius hält von der Burg Cenarius aus ständige Wache. Der bronzene Drachenschwarm, die Brut Nozdormus, ist zum ersten Mal seit zehntausend Jahren in die Wüste zurückgekehrt.",
		source = "https://warcraft.wiki.gg/wiki/Silithus_(Classic)",
	},
	[1452] = {
		name = "Winterspring",
		short = "Über Moonglade steigt der Berg durch eine dichte weiße Wolkenbank an, und dahinter liegt Winterspring. Die Luft ist hier oben klar und scharf.",
		full = "Über Moonglade steigt der Berg durch eine dichte weiße Wolkenbank an, und dahinter liegt Winterspring. Die Luft ist hier oben klar und scharf. Schnee bedeckt den Boden, und wenn er nicht fällt, scheint oft die Sonne.\n\nDie Bäume wurden in der Schlacht am Berg Hyjal zu seltsamen Formen verbogen, und Wurzeln des Weltenbaums ragen frei empor und wölben sich wie gewaltige Eichenbögen über den Köpfen. Vor Tausenden von Jahren, nach der Großen Zerschlagung, kamen Nachtelfen in dieses Tal, um neu zu beginnen. Ein älterer Streit zieht sich hindurch, zwischen bösartigen blauen Drachen und den weißen Frostsäblern, die über die Hänge streifen.\n\nDieser Kampf erschüttert das Tal noch immer. Die Streitkräfte des Zauberdrachen Cobaltann stoßen mit den Nachtelfen zusammen, die sie von den Hängen des Bergs Hyjal vertreiben wollen. Dämonen haben die südlichen Teile des Landes vollständig an sich gerissen. Goblins halten die Handelsstadt Everlook.",
		source = "https://warcraft.wiki.gg/wiki/Winterspring_(Classic)",
	},
	[1453] = {
		name = "Stormwind",
		short = "Orcs der Horde brannten Stormwind im Ersten Krieg nieder. Nach dem Zweiten Krieg kehrten die Menschen in die Ruinen zurück, und die Steinmetzgilde baute die Stadt in weißem Stein wieder auf.",
		full = "Orcs der Horde brannten Stormwind im Ersten Krieg nieder. Nach dem Zweiten Krieg kehrten die Menschen in die Ruinen zurück, und die Steinmetzgilde baute die Stadt in weißem Stein wieder auf. Die Arbeit kostete mehr, als die Krone zahlen konnte. Die Adligen hatten einen riesigen Schuldenberg angehäuft, weil sie die Armee über den Wald von Elwynn und bis ins Schlingendorntal verteilt hatten, und die Gebühren der Gilde blieben unbezahlt.\n\nAls Gildenmeister Edwin VanCleef sie einforderte, ordnete das Adelshaus die Auflösung der Gilde an. Unruhen folgten, und bei ihnen kam Königin Tiffin Wrynn versehentlich ums Leben. König Varian Wrynn schwor, die Verantwortlichen zu bestrafen, und ging hart gegen die Aufständischen vor. Die Steinmetze flohen aus der Stadt und versteckten sich in Westfall, wo sie zur Bruderschaft der Defias wurden.\n\nKönig Varian ist seither unter verdächtigen Umständen verschwunden. Sein junger Sohn, Prinz Anduin, erhielt die Krone, damit die Ordnung gewahrt bleiben konnte, und Hochlord Bolvar Fordragon dient als Regent und befehligt die Streitkräfte des Königreichs.",
		source = "https://warcraft.wiki.gg/wiki/Stormwind_City",
	},
	[1454] = {
		name = "Orgrimmar",
		short = "Bald nach der Schlacht am Berg Hyjal führte Kriegshäuptling Thrall sein Volk an ein kahles Stück Küste von Kalimdor.",
		full = "Bald nach der Schlacht am Berg Hyjal führte Kriegshäuptling Thrall sein Volk an ein kahles Stück Küste von Kalimdor. Das Land nannte er Durotar, nach seinem verstorbenen Vater Durotan, und die Festung, die er dort errichtete, nannte er Orgrimmar, nach seinem Freund und Mentor Orgrim Schicksalshammer. Sie entstand schnell und war dafür gebaut, Bestand zu haben. Starke Mauern, mächtige Tore und hohe Türme schützen sie, und die Berge in ihrem Rücken wurden zu Teilen der Festung selbst ausgehauen.\n\nDer Fluch auf den Orcs war gebrochen, und die Horde war kein Koloss mehr, der auf Krieg aus war. Thralls Volk wollte überleben und gedeihen. Goblins, Tauren und Trolle der Darkspear halfen beim Bau der Stadt, ebenso der Mok'Nathal Rexxar. Zentauren, Harpyien und Stacheleber machten den Erbauern Ärger, doch die Stadt blühte auf.\n\nOrcs und Trolle der Darkspear leben jetzt hier, dazu Tauren und die Verlassenen, die die Horde vor Kurzem aufgenommen hat. Alte Schamanen geben ihr Wissen an die neuesten Anführer der Horde weiter, und Klingenwinde fegen so heftig durch die Täler, dass sie schlecht gebauten Häusern die Dächer abreißen.",
		source = "https://warcraft.wiki.gg/wiki/Orgrimmar",
	},
	[1455] = {
		name = "Ironforge",
		short = "Die ersten Zwerge zogen aus Uldaman und gingen nach Westen in die Berge von Dun Morogh.",
		full = "Die ersten Zwerge zogen aus Uldaman und gingen nach Westen in die Berge von Dun Morogh. Sie gruben sich in den höchsten Gipfel, errichteten einen Altar für Khaz'goroth, den Titanen, den sie ihren Vater nannten, und bauten darunter die Große Schmiede. Eine Stadt wuchs um das Feuer und nahm ihren Namen von der Schmiede.\n\nIronforge ist eine in den Berg geschlagene Höhle, ihre Hallen liegen in Ringen um die Große Schmiede in ihrem Herzen, mit kleineren Ebenen tiefer unter der Erde. Wasserfälle aus geschmolzenem Gestein laufen die Wände hinab, Läden sind in den Stein gebaut, und in jedem Gasthaus brüllen Kamine. Die Stimmung des Ortes ist geschäftig, derb und industriell, und doch gemütlich, und zwergisches Lachen hallt zu jeder Stunde durch die Gänge.\n\nAls die Horde im Zweiten Krieg über Khaz Modan hinwegfegte, fiel eine zwergische Festung nach der anderen, und die Überlebenden jeder von ihnen flohen nach Ironforge. Kilrogg Totauge und sein Klan des Blutenden Auges kämpften monatelang gegen die Zwerge und konnten die Stadt nicht einnehmen. König Magni Bronzebeard herrscht jetzt hier, und die aus Gnomeregan vertriebenen Gnome haben ein eigenes Viertel bekommen, die Tüftlerstadt.",
		source = "https://warcraft.wiki.gg/wiki/Ironforge",
	},
	[1456] = {
		name = "Thunder Bluff",
		short = "Unzählige Generationen lang zogen die Tauren umher, und die Zentauren jagten sie über die Ebenen. Dann kamen Kriegshäuptling Thrall und die Horde nach Kalimdor.",
		full = "Unzählige Generationen lang zogen die Tauren umher, und die Zentauren jagten sie über die Ebenen. Dann kamen Kriegshäuptling Thrall und die Horde nach Kalimdor. Mit ihrer Hilfe trieben Cairne Bloodhoof und sein Stamm die Zentauren zurück und nahmen das Grasland von Mulgore ein. Zum ersten Mal seit Hunderten von Jahren hatten die Tauren eigenes Land.\n\nCairne baute seine Zuflucht auf einer Reihe windgepeitschter Tafelberge, hoch über dem Gras. Aufzüge aus Seil und Holz, eine Erfindung, die allein den Tauren eigen ist, heben die Leute vom Fuß der Felsen nach oben, und lange Brücken derselben Machart überspannen die Lücken zwischen den Tafelbergen. Zelte, Langhäuser und bemalte Totems stehen auf jedem Gipfel.\n\nTauren aller Stämme sind hier willkommen, und die verstreuten Stämme haben sich unter Cairnes Führung zusammengefunden. Einige sind anderer Meinung als er darüber, welche Richtung die neue Nation einschlagen soll. Alle sind sich einig, dass niemand weiser ist als er.",
		source = "https://warcraft.wiki.gg/wiki/Thunder_Bluff",
	},
	[1457] = {
		name = "Darnassus",
		short = "Die Unsterblichkeit endete für die Nachtelfen nach dem Dritten Krieg, und viele konnten Alter, Krankheit und Gebrechlichkeit nicht ertragen.",
		full = "Die Unsterblichkeit endete für die Nachtelfen nach dem Dritten Krieg, und viele konnten Alter, Krankheit und Gebrechlichkeit nicht ertragen. Eine Reihe von Druiden machte sich auf, sie zurückzugewinnen, indem sie einen großen Baum pflanzten, der ihre Geister wieder mit der ewigen Welt verbinden sollte. Da Malfurion Stormrage vermisst wurde, wurde Fandral Staghelm, der sie angeführt hatte, Erzdruide. Der Baum, Teldrassil, wuchs über den Wolken vor der stürmischen Küste im Norden von Kalimdor. In seinen dämmrigen Ästen schlug die Stadt Darnassus Wurzeln, erbaut zu Ehren des Überlebens der Nachtelfen.\n\nDie Stadt liegt um einen See und ist nach oben offen zum Himmel. Anmutige Brücken überqueren das Wasser und halten die Gebäude weit auseinander, sodass nichts beengt wirkt. Hütten aus bearbeitetem Holz und gepflegte Haine säumen die Ufer, und gefallene Blätter bedecken die Wege. Der Tempel des Mondes erhebt sich wie ein Leuchtfeuer über den Bäumen. Hohepriesterin Tyrande Whisperwind herrscht von dort, und die Schildwachen halten Wache über die Stadt. Sie bleibt eine stille Zuflucht und ein Denkmal für ein Volk, das lernt, mit der Sterblichkeit zu leben.",
		source = "https://warcraft.wiki.gg/wiki/Darnassus",
	},
	[1458] = {
		name = "Undercity",
		short = "Undercity war alt, bevor die Verlassenen sie beanspruchten. Tief unter dem Palast von Lordaeron lagen die uralten Grüfte und Katakomben seiner toten Könige, dazu die Kerker und Kanäle der Stadt.",
		full = "Undercity war alt, bevor die Verlassenen sie beanspruchten. Tief unter dem Palast von Lordaeron lagen die uralten Grüfte und Katakomben seiner toten Könige, dazu die Kerker und Kanäle der Stadt. Sie war nur für Gefangene und Leichen gedacht, doch die Ärmsten von Lordaerons Bevölkerung lebten trotzdem dort, und die Streifen der Wachen, um sie zu vertreiben, hielten nie lange vor.\n\nArthas Menethil wollte, dass Undercity der Machtsitz der Geißel in Lordaeron würde. Er ließ eine kleine Schar Untote zurück, die Katakomben unter der zerstörten Hauptstadt auszuheben, und dann rief der Lichkönig ihn fort. Als der Griff des Lichkönigs sich lockerte, führte Fürstin Sylvanas Windrunner eine Gruppe Untoter mit freiem Willen aus der Geißel hinaus. Sie lockte Arthas in eine Falle, doch er entkam. Als der Kampf um Lordaeron vorüber war, nannte sie ihre Anhänger die Verlassenen und nahm die zerstörte Hauptstadt für sich in Besitz.\n\nDie Verlassenen verbrachten Jahre damit, das Labyrinth aus Katakomben zu vollenden, das die Geißel begonnen hatte. Flüsse aus giftigem Schlamm laufen durch jede Allee, und die Dämpfe machen den Ort für die lebenden Mitglieder der Horde fast unerträglich. Für Sylvanas und ihr verfluchtes Volk ist er eine Zuflucht in einer Welt, die ihresgleichen fürchtet und jagt, und sie haben geschworen, die Geißel aus dem Land zu vertreiben.",
		source = "https://warcraft.wiki.gg/wiki/Undercity",
	},
	[2482] = {
		name = "Hyjal",
		short = "Der Berg Hyjal war den Nachtelfen heilig, und Königin Azshara hielt ihr Reich von ihm fern. Als der erste Brunnen der Ewigkeit zerstört wurde und die Welt zerbrach, hielt der Berg stand.",
		full = "Der Berg Hyjal war den Nachtelfen heilig, und Königin Azshara hielt ihr Reich von ihm fern. Als der erste Brunnen der Ewigkeit zerstört wurde und die Welt zerbrach, hielt der Berg stand. Der nachtelfische Widerstand war auf seinen Gipfel entkommen, und von dort aus machten sie sich daran, ihre Gesellschaft wieder aufzubauen, diesmal ohne arkane Magie.\n\nNach der Großen Zerschlagung schuf Illidan Stormrage auf dem Gipfel des Berges einen zweiten Brunnen der Ewigkeit. Die Nachtelfen pflanzten den Weltenbaum Nordrassil darüber. Drei Drachenaspekte segneten den Baum, Alexstrasza, Nozdormu und Ysera. Seine Wurzeln breiteten sich durch den Berg aus, heilten das Land und hielten die Nachtelfen frei von Alter und Krankheit.\n\nIm Dritten Krieg führte der Dämon Archimonde die Brennende Legion die Hänge hinauf, um den zweiten Brunnen an sich zu reißen. Orcs, Menschen und Nachtelfen leisteten gemeinsam Widerstand. Am Ende sammelten sich die Irrwische von Hyjal in Nordrassil, und die Explosion vernichtete Archimonde. Sie raubte dem Baum auch seine Verzauberungen, und die Nachtelfen verloren ihre Unsterblichkeit. Sie pflanzten Teldrassil und verlegten ihre Hauptstadt dorthin.",
		source = "",
	},
	[2521] = {
		name = "Insel Zephras",
		short = "Vor fast zehntausend Jahren führte ein maskierter Rebell, genannt der Shal'nan, einen Aufstand gegen Prinz Tortheldrin in der Stadt der Hochgeborenen, Eldre'Thalas, an.",
		full = "Vor fast zehntausend Jahren führte ein maskierter Rebell, genannt der Shal'nan, einen Aufstand gegen Prinz Tortheldrin in der Stadt der Hochgeborenen, Eldre'Thalas, an. Er endete in einer Nacht wilder Magie und vieler Toter. Die Rebellen flohen mit der Flotte des Prinzen im Rücken über das Meer nach Westen und fanden ein Land, das von Windgeistern beherrscht wurde. Die Geister schlossen einen Handel mit ihnen, hoben einen großen Teil dieses Landes in den Himmel und verankerten ihn im Himmelswall, der Ebene der Luft. Das ist die Insel Zephras.\n\nDie Himmelsbewohner, die Nachkommen der Verbannten, leben seither hier, und der Himmel hat sie verändert. Sie sind schlank und leicht geworden, und ein wachsender Teil ihrer Kinder kommt mit blauer Haut zur Welt. Nun sind die Windgeister fort, und niemand auf der Insel kann sagen, warum. Die uralten Pylonen, die die Insel oben halten, versagen. Andere Inseln der Himmelsbewohner brechen auseinander, ihre Flüchtlinge drängen sich auf Zephras, und Zephras selbst beginnt zu zerfallen.\n\nDrei Mächte ringen um das, was übrig ist. Der Hohe Orden sucht das arkane Wissen seiner Ahnen, der Hochgeborenen. Die Windformer halten am alten Band mit den Elementen fest. Der Al'Aketh-Kult dient Al'Akir dem Windfürsten.",
		source = "",
	},
	[2524] = {
		name = "Darkspear-Inseln",
		short = "Ein Sturm zerstreute Thralls gestohlene Flotte, als die Schiffe von Großadmiral Daelin Proudmoore sie über das Meer jagten.",
		full = "Ein Sturm zerstreute Thralls gestohlene Flotte, als die Schiffe von Großadmiral Daelin Proudmoore sie über das Meer jagten. Die beschädigten Orc-Schiffe fanden eine Bucht an einer Inselkette mit einem aktiven Vulkan und liefen ein, um sich zu reparieren. Hier lebten die Trolle der Darkspear. Sie hatten das Schlingendorntal verlassen, weil die anderen Stämme der Gurubashi sie grausam behandelten, und waren nach Westen gesegelt, um sich auf diesen Inseln niederzulassen.\n\nDer Hexendoktor Sen'jin traf die Orcs in Frieden und sagte Thrall, er habe ihn in einer Vision gesehen. Seeleute aus Kul Tiras, die von Daelins Flotte gestrandet waren, hatten auf den Inseln einen Außenposten errichtet und lagen mit den Trollen im Krieg. Mitten im Kampf nahmen Murlocs Thrall, Sen'jin und die Menschen gefangen und trugen sie in Höhlen unter dem Vulkan. Thrall kämpfte sich frei und erreichte den Altar der Murlocs, doch Sen'jin war schon tödlich verwundet. Mit seinen letzten Worten sagte er Thrall, seine Visionen zeigten, wie Thrall die Trolle fortführt. Die Darkspear segelten der Horde nach.\n\nNun kämpfen die Darkspear-Plünderer und die Expeditionstruppe von Theramore um die Inseln.",
		source = "",
	},
	[2548] = {
		name = "Flusslande",
		short = "Stormwind gab die Flussauen im Ersten Krieg auf. Die Alte Horde überrannte die Region, und das Königreich entschied, seine Soldaten seien daheim besser aufgehoben.",
		full = "Stormwind gab die Flussauen im Ersten Krieg auf. Die Alte Horde überrannte die Region, und das Königreich entschied, seine Soldaten seien daheim besser aufgehoben. Die Bruderschaft des Pferdes, eine Ritterkompanie, blieb, um zu kämpfen. Seit zwanzig Jahren versuchen sie, das Land zurückzugewinnen, und ihr Anführer Demar Brant hält die Männer von Stormwind für Feiglinge, die sich hinter ihren Mauern verstecken. Ihre Festung ist Burg Farholde.\n\nGegen Ende des Zweiten Krieges flohen Oger des Schattenhammers und Orcs der Sturmreiter nach Osten und schlossen sich den Ogern an, die sich hier bereits niedergelassen hatten. Sie halten einen Großteil des Landes jenseits der Reichweite der Bruderschaft. Der Hauptfluss windet sich hindurch und bildet drei Altwasserseen.",
		source = "",
	},
	[2652] = {
		name = "Shen'dralas",
		short = "Nördlich von Düsterbruch liegt Shen'dralas, einst ein Teil der Stadt der Hochgeborenen, Eldre'Thalas. Freundliche Geister der Shen'dralar spuken noch in seinen Ruinen.",
		full = "Nördlich von Düsterbruch liegt Shen'dralas, einst ein Teil der Stadt der Hochgeborenen, Eldre'Thalas. Freundliche Geister der Shen'dralar spuken noch in seinen Ruinen. Auch Zentauren der Magram und Borstennacken-Stacheleber erheben hier Anspruch auf Land, und das Land ist zwischen allen dreien umkämpft. Es liegt südöstlich von Desolace, zwischen Feralas und Mulgore.",
		source = "",
	},
}

